from lib import *
S = SS('t3')
steps = [
    step("协调者作为独立进程,在 2PC 的五个位置各被 kill -9 一次(退出码都是 -9),看两个参与者当场停在什么状态。位置 0(开始之前):两边都没有 prepared 事务,订单 0、库存 100。位置 1(第一个参与者 prepare 之后):订单库有 1 个 prepared 事务,库存库 0。位置 2(全部 prepare 之后、写决定日志之前):两边各 1 个 prepared,决定日志里没有记录。位置 3(决定日志落盘之后、发出第一个 COMMIT PREPARED 之前):两边各 1 个 prepared,日志里是 COMMIT。位置 4(第一个 COMMIT PREPARED 之后):订单库已提交(订单 1 条),库存库还是 prepared(库存仍是 100)。位置 1 到 4 的参与者都停在“已承诺、等决定”的状态,自己无权决定。", t=tl(S(1)), mark=lidx(S(1), '2. 全部 prepare 之后', '3. 决定日志落盘之后'), done=lidx(S(1), '4. 第一个 COMMIT PREPARED 之后'), b=bars([['位置 1:prepared 事务总数', 1, '1(订单库)'], ['位置 2:prepared 事务总数', 2, '2(两边各一)'], ['位置 3:prepared 事务总数', 2, '2(日志已是 COMMIT)'], ['位置 4:prepared 事务总数', 1, '1(订单库已提交)']], 2, mark=[1, 2], done=[3]), kv=KV([['位置 0', '什么都没留下'], ['位置 1~3', '参与者已 prepare,等协调者'], ['位置 4', '一边已提交,一边仍 prepared']], ['位置 4'])),
    step("两边都已 prepare、协调者死了(位置 2),参与者只能干等:库存库 pg_prepared_xacts 里 xw 的年龄从 0.0 秒涨到 4.0 秒。业务会话 UPDATE 被 prepare 的那一行 sku-1,等了 3001.3 ms 后 lock timeout;同一会话 UPDATE 别的行 sku-2 用 0.8 ms 就完成,锁的粒度是被 prepare 的那一行。它还挡住 VACUUM:churn 表(2000 行)整体 UPDATE 3 次后 VACUUM,“6000 are dead but not yet removable”,removable cutoff 卡在 741;ROLLBACK PREPARED 之后再 VACUUM,6000 个死元组被清掉(removed),cutoff 前进到 750。一个没人管的 prepared 事务,会一直占着行锁并阻碍清理。", t=tl(S(2)), mark=lidx(S(2), '等了 3001.3 ms', '6000 are dead but not yet removable'), done=lidx(S(2), '6000 removed'), b=bars([['被卡的那行 UPDATE 等待 ms', 3001.3, '3001.3(超时)'], ['别的行 UPDATE ms', 0.8, '0.8'], ['挂着时 VACUUM 不能清的死元组', 6000, '6000'], ['回滚后 VACUUM 清掉的死元组', 6000, '6000']], 3100, mark=[0, 2], done=[3], cur=[1]), kv=KV([['行锁', '被 prepare 的行一直被锁'], ['别的行', '不受影响'], ['VACUUM', '死元组清不掉,直到事务收尾']], ['VACUUM'])),
    step("位置 4:订单库已提交、库存库还是 prepared,协调者死了。库存库的人只看得到本库有一个 prepared 事务;去订单库看,pg_prepared_xacts 里已经没有它——没有可能是已提交,也可能是已回滚,看不出来。做法 A(等不到协调者就自己回滚):库存库 ROLLBACK PREPARED,结果订单 1 条、库存 100,不一致(订单已提交,库存没扣)。做法 B(去问协调者留下的决定日志):日志里是 COMMIT,库存库 COMMIT PREPARED,订单 1 条、库存 99,一致。参与者自己没法安全地决定,必须有人知道协调者当初的决定。", t=tl(S(3)), mark=lidx(S(3), '做法 A', '不一致(订单已经提交了'), done=lidx(S(3), '做法 B', '一致'), b=bars([['做法 A:订单数', 1, '1'], ['做法 A:库存扣了', 0, '0(不一致)'], ['做法 B:订单数', 1, '1'], ['做法 B:库存扣了', 1, '1(一致)']], 1, mark=[0, 1], done=[2, 3]), kv=KV([['参与者能看到', '只有本库的 prepared 状态'], ['对方没有 prepared', '分不清已提交还是已回滚'], ['能安全决定的', '只有读过协调者决定的人']], ['能安全决定的'])),
    step("协调者重启后扫描两边的 pg_prepared_xacts:决定日志里是 COMMIT 就 COMMIT PREPARED,没有记录就 ROLLBACK PREPARED。五个位置全部恢复到一致:位置 0 无事可做(订单 0、库存 100);位置 1 回滚订单库的那个(0、100);位置 2 两边都回滚(0、100);位置 3 两边都提交(订单 1、库存 99);位置 4 库存库补上 COMMIT(1、99)。有了这份日志,协调者死多少次都能把事务收尾,代价是等它回来之前一直处于第二步描述的阻塞里。", t=tl(S(4)), mark=lidx(S(4), '3. 决定日志落盘之后', '4. 第一个 COMMIT PREPARED 之后'), done=lidx(S(4), '2. 全部 prepare 之后', '1. 第一个参与者'), kv=KV([['日志里有 COMMIT', '补发 COMMIT PREPARED'], ['日志里没有', 'presumed abort,回滚'], ['前提', '协调者的日志还在']], ['前提'])),
    step("如果协调者的决定日志丢了(磁盘坏了),恢复程序只能一律回滚。位置 0 到 2 仍然一致(0、100)。位置 3 也“一致”(0、100),但那是把本来已经决定提交的事务回滚了;位置 4 订单库已经提交,库存库被回滚,订单 1 条、库存 100,不一致,只能人工补。决定日志是 2PC 里最关键的一份数据,它丢了,事务的结局就没人知道了。", t=tl(S(5)), mark=lidx(S(5), '4. 第一个 COMMIT PREPARED 之后', '位置 3 虽然'), done=lidx(S(5), '0. 开始之前'), b=bars([['位置 4 订单数', 1, '1'], ['位置 4 库存扣了', 0, '0']], 1, mark=[0, 1]), kv=KV([['日志丢了', '只能一律回滚'], ['位置 3', '把已决定提交的事务回滚了'], ['位置 4', '不一致,要人工补']], ['位置 4'])),
    step("决定日志必须在发出任何 COMMIT PREPARED 之前落盘。把顺序调换(先发第一个 COMMIT PREPARED,再写日志),在位置 4 杀协调者:崩溃时决定日志里没有记录,恢复程序按“没记录就回滚”处理库存库,订单 1 条、库存 100,不一致。正确顺序下同一个位置:日志是 COMMIT,库存库补 COMMIT,订单 1 条、库存 99,一致。写日志与发命令的先后,就是 2PC 能不能恢复的分水岭。", t=tl(S(6)), mark=lidx(S(6), '先发第一个 COMMIT PREPARED 再写日志(错误)'), done=lidx(S(6), '先写日志再发 COMMIT PREPARED(正确)'), b=bars([['正确顺序:库存扣了', 1, '1(一致)'], ['错误顺序:库存扣了', 0, '0(不一致)']], 1, done=[0], mark=[1]), kv=KV([['先写日志', '崩溃后可恢复'], ['先发命令', '崩溃时日志是空的'], ['教训', '决定要先落盘再通知']], ['教训'])),
    step("另一半:参与者在投票之前死了。库存库在订单库 PREPARE 成功之后、轮到自己之前被 kill -9,协调者向它发 SQL 时报 “server closed the connection unexpectedly”,于是进入回滚:订单库的 prepared 事务被 ROLLBACK PREPARED,决定日志记 ABORT,订单 0 条。库存库重启后没有 prepared 事务、库存 100。没有投 YES 就死了什么都没留下,整体干净地 ABORT。2PC 的危险集中在“已经投了 YES 之后”,投票前的失败是安全的。", t=tl(S(7)), mark=lidx(S(7), '阶段一失败'), done=lidx(S(7), '协调者的结论:ABORT', '库存库重启后'), kv=KV([['投票前参与者死', '协调者 ABORT,干净回滚'], ['投 YES 之后', '才会陷入等待决定'], ['协调者的日志', '记 ABORT']], ['投 YES 之后'])),
]
A = mkartt('t3', 3, '分布式事务,两阶段提交,2PC,协调者崩溃,PostgreSQL,真实验证,动画演示',
    '实测 2PC 里协调者在五个位置被 kill -9:参与者停在已承诺等决定的状态,行锁一直握着(同一行 UPDATE 等到超时)并挡住 VACUUM;参与者自己回滚会造成不一致;有决定日志可恢复,没有日志位置 4 不一致;先发 COMMIT PREPARED 再写日志也不一致。',
    '2PC 最让人担心的是协调者崩溃。它在不同位置崩溃时,参与者分别停在哪?能自己决定吗?靠什么恢复?这篇把协调者作为独立进程,在五个位置各 kill -9 一次,用真实的 PostgreSQL 把每种结局都跑出来。',
    [('4 / 5', '五个崩溃位置里,协调者死后至少有一个参与者停在已 prepare 等决定的位置数(位置 1 到 4)'), ('3001.3 ms', '业务会话 UPDATE 被 prepare 的那一行,等到 lock_timeout 超时的时间'), ('6000', '挂着一个 prepared 事务时,VACUUM 清不掉的死元组数')],
    [('五个崩溃位置', '<p>协调者在开始前、第一个 prepare 后、全部 prepare 后写日志前、写日志后、第一个 COMMIT PREPARED 后各被杀一次。位置 1 到 4 都有参与者停在已承诺、等决定的状态,位置 4 还出现一边已提交、一边仍 prepared。</p>'),
     ('阻塞的代价', '<p>被 prepare 的行一直被锁,别的事务写同一行等到超时;它还让 VACUUM 的 removable cutoff 停住,死元组清不掉。直到有人收尾它。</p>'),
     ('参与者不能自己决定', '<p>对方不再 prepared 时,可能已提交,也可能已回滚,从自己这边分不出来。单方面回滚会造成订单已提交、库存没扣。</p>'),
     ('靠决定日志收尾', '<p>协调者重启后按日志:有 COMMIT 补 COMMIT PREPARED,没记录就回滚。五个位置都恢复一致。</p>'),
     ('日志丢了怎么办', '<p>一律回滚时,位置 4 必然不一致,位置 3 则把已决定提交的事务回滚了。日志是 2PC 里最关键的数据。</p>'),
     ('写日志的先后', '<p>先写日志再发命令,才能恢复;反过来,崩溃时日志是空的,恢复程序只能回滚,结果不一致。</p>'),
     ('参与者先死', '<p>参与者在投 YES 之前死,协调者 ABORT 并回滚其它已 prepare 的参与者,干净。危险都在投了 YES 之后。</p>')],
    steps,
    [ENV_T + '。本篇用两个独立的 PostgreSQL 16.15 实例和我自己写的协调者(tools/articles/tpc.py,独立进程,在代码里的指定位置 kill -9 自己);决定日志在 SQLite 里(synchronous=FULL);恢复程序是同一个文件里的 recover()',
     '没有验证:多于两个参与者;协调者崩溃后用另一个协调者实例接管(这里是同一份日志、同一个程序重启);合作终止协议(参与者之间互相问);XA 协议在 MySQL 里的行为(下一篇);长时间(分钟 / 小时级)阻塞下参与者资源的耗尽;max_prepared_transactions 用满后的表现'],
    '协调者崩溃')
